%dw 2.0
import computeStatuses from modules::usage
output application/java
var cfg = { entitlements: [
	{ key: "msgs",  name: "Mule Messages", usage_model: "DRAWDOWN",       limit: 100, unit: "m" },
	{ key: "flows", name: "Mule Flows",    usage_model: "HIGH_WATERMARK", limit: 10,  unit: "f" },
	{ key: "tok",   name: "Tokens",        usage_model: "MONITOR",        limit: 0,   unit: "t" }
]}
var records = [
	{ meter_key: "msgs",  period: "2026-08", usage_value: 50 },
	{ meter_key: "msgs",  period: "2026-09", usage_value: 40 },
	{ meter_key: "flows", period: "2026-08", usage_value: 7 },
	{ meter_key: "flows", period: "2026-09", usage_value: 5 },
	{ meter_key: "tok",   period: "2026-08", usage_value: 999 },
	{ meter_key: "tok",   period: "2026-09", usage_value: 123 }
]
var s = computeStatuses(cfg, records, "2026-09", 80, 95, "2026-09-30T00:00:00Z")
---
{ msgs: s[0], flows: s[1], tok: s[2] }
